// One seal or one open for files.ts, in a worker of its own: the main thread
// keeps sending voice meanwhile. The page ends the worker afterwards, and the
// wasm memory a big file grew (some 190 MiB for 64 MiB) goes with it. A
// picture somebody else made is opened and sanitized here in one job
// (media.ts), so only the PNG written for it ever reaches the page.

// Generated by `npm run build:wasm` (wasm-pack --target web).
// @ts-ignore — the package only exists after the wasm build
import { initSync, openFile, sealFile } from "../../lib/wasm/voipc_web.js";
import { checkOpenInput, checkSealInput } from "./wasm";
import { readPackIn, sanitizeIn, stripIn } from "./media";

self.onmessage = (e: MessageEvent) => {
  const job = e.data;
  try {
    if (job.op === "sanitize") {
      const out = sanitizeIn(job.media, job.bytes, job.profile, job.maxOut);
      self.postMessage({ ok: out }, { transfer: out.still ? [out.png.buffer, out.still.buffer] : [out.png.buffer] });
      return;
    }
    if (job.op === "strip") {
      const out = stripIn(job.media, job.bytes);
      self.postMessage({ ok: out }, { transfer: [out.buffer] });
      return;
    }
    if (job.op === "pack") {
      const pack = readPackIn(job.media, job.bytes);
      self.postMessage({ ok: pack }, { transfer: pack.entries.map((e) => e.bytes.buffer) });
      return;
    }
    // The page compiled the module once; instantiating it here is cheap
    initSync({ module: job.module });
    if (job.op === "image") {
      // Opened and sanitized here: the file's own bytes never leave the worker
      checkOpenInput(job.size, job.blob);
      const plain = openFile(job.hash, job.key, job.size, job.z, job.blob);
      const out = sanitizeIn(job.media, plain, job.profile, 0, job.motion);
      self.postMessage({ ok: out }, { transfer: out.still ? [out.png.buffer, out.still.buffer] : [out.png.buffer] });
    } else if (job.op === "seal") {
      checkSealInput(job.plain);
      const sealed = sealFile(job.plain, job.compress);
      self.postMessage({ ok: sealed }, { transfer: [sealed.blob.buffer] });
    } else {
      // A blob the page gave up (`give`) goes back to it with the file
      const blob: Uint8Array = job.give ?? job.blob;
      checkOpenInput(job.size, blob);
      const plain = openFile(job.hash, job.key, job.size, job.z, blob);
      const back = job.give ? [plain.buffer, blob.buffer] : [plain.buffer];
      self.postMessage({ ok: { plain, blob: job.give ? blob : undefined } }, { transfer: back });
    }
  } catch (err) {
    // An Error's name is a FileErrorName (wasm.ts)
    const e = err as Error;
    self.postMessage({ error: { name: e?.name ?? "Error", message: e?.message ?? String(err) } });
  }
};
